vector<vector<int>> adj;
vector<int> disc, fin;
vector<bool> visited;
int timestamp = 1;

void dfs(int u) {
    visited[u] = true;
    disc[u] = timestamp++;

    // Sort adjacency list to visit smallest ID first
    sort(adj[u].begin(), adj[u].end());

    for (int v : adj[u]) {
        if (!visited[v]) {
            dfs(v);
        }
    }

    fin[u] = timestamp++;
}

