#include <stdio.h>
#include <stdlib.h>

#define MAX_VERTICES 100

typedef struct Node {
    int vertex;
    struct Node* next;
} Node;

typedef struct Graph {
    int numVertices;
    Node* adjLists[MAX_VERTICES];
} Graph;

Graph* createGraph(int vertices) {
    Graph* graph = malloc(sizeof(Graph));
    graph->numVertices = vertices;
    for (int i = 0; i < vertices; i++) {
        graph->adjLists[i] = NULL;
    }
    return graph;
}

void addEdge(Graph* graph, int src, int dest) {
    Node* newNode = malloc(sizeof(Node));
    newNode->vertex = dest;
    newNode->next = graph->adjLists[src];
    graph->adjLists[src] = newNode;
}

// Insert neighbor in sorted order (ascending by vertex ID)
void addEdgeSorted(Graph* graph, int src, int dest) {
    Node* newNode = malloc(sizeof(Node));
    newNode->vertex = dest;

    if (graph->adjLists[src] == NULL || graph->adjLists[src]->vertex > dest) {
        newNode->next = graph->adjLists[src];
        graph->adjLists[src] = newNode;
        return;
    }

    Node* current = graph->adjLists[src];
    while (current->next != NULL && current->next->vertex < dest) {
        current = current->next;
    }
    newNode->next = current->next;
    current->next = newNode;
}

void dfsVisit(Graph* graph, int vertex, int* visited, int* discovery, int* finish, int* time) {
    visited[vertex] = 1;
    (*time)++;
    discovery[vertex] = *time;

    Node* temp = graph->adjLists[vertex];
    while (temp) {
        int adjVertex = temp->vertex;
        if (!visited[adjVertex]) {
            dfsVisit(graph, adjVertex, visited, discovery, finish, time);
        }
        temp = temp->next;
    }

    (*time)++;
    finish[vertex] = *time;
}

void dfs(Graph* graph) {
    int visited[MAX_VERTICES] = {0};
    int discovery[MAX_VERTICES];
    int finish[MAX_VERTICES];
    int time = 0;

    for (int i = 0; i < graph->numVertices; i++) {
        if (!visited[i]) {
            dfsVisit(graph, i, visited, discovery, finish, &time);
        }
    }

    for (int i = 0; i < graph->numVertices; i++) {
        printf("%d %d %d\n", i, discovery[i], finish[i]);
    }
}

void freeGraph(Graph* graph) {
    for (int i = 0; i < graph->numVertices; i++) {
        Node* temp = graph->adjLists[i];
        while (temp) {
            Node* toFree = temp;
            temp = temp->next;
            free(toFree);
        }
    }
    free(graph);
}

int main() {
    int vertices;
    scanf("%d", &vertices);

    Graph* graph = createGraph(vertices);

    for (int i = 0; i < vertices; i++) {
        int adjCount;
        scanf("%d", &adjCount);
        for (int j = 0; j < adjCount; j++) {
            int neighbor;
            scanf("%d", &neighbor);
            addEdgeSorted(graph, i, neighbor);
        }
    }

    dfs(graph);
    freeGraph(graph);

    return 0;
}

