typedef struct Node {
    int v;
    struct Node *next;
} Node;

int n;
Node **adj;
int *color, *d, *f;
int timer = 0;

void add_edge(int u, int v) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->v = v;
    node->next = NULL;

    if (adj[u] == NULL) {
        adj[u] = node;
    } else {
        Node *cur = adj[u];
        while (cur->next) cur = cur->next;
        cur->next = node;
    }
}

void dfs_visit(int u) {
    color[u] = 1;
    d[u] = ++timer;

    Node *cur = adj[u];
    while (cur) {
        int v = cur->v;
        if (color[v] == 0) {
            dfs_visit(v);
        }
        cur = cur->next;
    }

    color[u] = 2;
    f[u] = ++timer;
}

int main(void) {
    if (scanf("%d", &n) != 1) return 0;

    adj = (Node **)calloc(n + 1, sizeof(Node *));
    color = (int *)calloc(n + 1, sizeof(int));
    d = (int *)calloc(n + 1, sizeof(int));
    f = (int *)calloc(n + 1, sizeof(int));

    for (int i = 0; i < n; i++) {
        int u, k;
        scanf("%d %d", &u, &k);
        for (int j = 0; j < k; j++) {
            int v;
            scanf("%d", &v);
            add_edge(u, v);
        }
    }

    for (int u = 1; u <= n; u++) {
        if (color[u] == 0) dfs_visit(u);
    }

    for (int u = 1; u <= n; u++) {
        printf("%d %d %d\n", u, d[u], f[u]);
    }

    return 0;
}

