public class Main {
    static List<Integer>[] graph;
    static int[] color; // 0: unvisited, 1: visiting, 2: finished
    static int[] discover;
    static int[] finish;
    static int time = 0;

    static void dfs(int u) {
        color[u] = 1;
        discover[u] = ++time;

        for (int v : graph[u]) {
            if (color[v] == 0) {
                dfs(v);
            }
        }

        color[u] = 2;
        finish[u] = ++time;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) graph[i] = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int u = fs.nextInt();
            int k = fs.nextInt();
            for (int j = 0; j < k; j++) {
                graph[u].add(fs.nextInt());
            }
        }

        color = new int[n + 1];
        discover = new int[n + 1];
        finish = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            if (color[i] == 0) dfs(i);
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            sb.append(i).append(' ')
              .append(discover[i]).append(' ')
              .append(finish[i]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
